INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'f5407781-07d1-42a8-8b5a-09f22986aac9', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Eo Gió', ARRAY['Eo Gio Cape','Eo Gió Quy Nhơn','Đèo Eo Gió','Khu du lịch Eo Gió']::text[], 'Một eo biển nhỏ hoang sơ tại xã Nhơn Lý, nổi tiếng với con đường đi bộ ven biển tuyệt đẹp và những vách đá hùng vĩ.', 'Eo Gió nằm cách trung tâm thành phố Quy Nhơn khoảng 20km tại xã Nhơn Lý. Đây là một khu vực eo biển nhỏ được bao bọc bởi hai dãy núi đá cao ôm trọn bãi biển xanh trong. Nơi đây nổi tiếng với con đường đi bộ có tay vịn màu đỏ trắng, mang đến những góc check-in cực đỉnh cho du khách.',
            'Xã Nhơn Lý, Quy Nhơn, Bình Định, Việt Nam', NULL, NULL, 'https://ik.imagekit.io/tvlk/blog/2024/07/I2jZ97hQ-dia-diem-du-lich-quy-nhon-0.jpg?tr=q-70,c-at_max,w-1000,h-600', 'https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-1.jpg?tr=q-70,c-at_max,w-1000,h-600', '[{"src": "https://ik.imagekit.io/tvlk/blog/2024/07/I2jZ97hQ-dia-diem-du-lich-quy-nhon-0.jpg?tr=q-70,c-at_max,w-1000,h-600", "alt": "Eo Gió"}, {"src": "https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-1.jpg?tr=q-70,c-at_max,w-1000,h-600", "alt": "Eo Gió"}, {"src": "https://cuongdulich.com/assets/posts/1614731134-eo-gio-quy-nhon-3.JPG", "alt": "Cung đường đi bộ tại Eo Gió"}, {"src": "https://cuongdulich.com/assets/posts/1614731241-eo-gio-quy-nhon-2.JPG", "alt": "Vẻ đẹp hoang sơ của Eo Gió"}, {"src": "https://dulichquynhon.blog/wp-content/uploads/2026/04/ky-co-eo-gio-7.webp", "alt": "Đèo Eo Gió chạy dọc sườn núi hướng ra biển"}, {"src": "https://dulichquynhon.blog/wp-content/uploads/2026/04/ky-co-eo-gio-8.webp", "alt": "Đèo Eo Gió chạy dọc sườn núi hướng ra biển"}]'::jsonb, NULL, NULL,
            9.3, '{"distance_from_center": "Khoảng 20km", "highlights": "Cung đường đi bộ lưng chừng núi, địa hình đón gió mát mẻ quanh năm", "reputation": "Được mệnh danh là nơi ngắm hoàng hôn đẹp nhất Việt Nam", "ticket_price": "25.000 VNĐ/người"}'::jsonb, '{"tags": ["Eo biển", "Check-in", "Ngắm cảnh", "Thiên nhiên", "Ngắm hoàng hôn", "Check-in sống ảo", "Cảnh quan kỳ vĩ", "Địa điểm chụp ảnh", "Bình minh", "Hoàng hôn"], "sentiment": "Very positive", "best_time_to_visit": "Mùa khô (từ tháng 3 đến tháng 9)", "suitable_for": ["Giới trẻ", "Gia đình", "Cặp đôi", "Người thích chụp ảnh", "Người yêu thiên nhiên", "Các bạn trẻ chụp ảnh", "Chụp ảnh nghệ thuật", "Phượt thủ"]}'::jsonb, '{"urls": ["https://www.traveloka.com/vi-vn/explore/destination/dia-diem-du-lich-quy-nhon-2/143408", "https://cuongdulich.com/dia-diem/2803-kinh-nghiem-du-lich-ky-co-eo-gio.html", "https://dulichquynhon.blog/dia-diem-du-lich/ky-co-eo-gio/"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn", "Kỳ Co Eo Gió Quy Nhơn có gì chơi"], "titles": ["15 địa điểm du lịch Quy Nhơn bạn không thể bỏ lỡ - Traveloka", "Kinh nghiệm du lịch Kỳ Co - Eo Gió trong 1 ngày chi tiết nhất có kèm ...", "Du Lịch Kỳ Co - Eo Gió: Đường Đi, Giá Vé và Review Chi Tiết"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Kỳ Co', ARRAY['Bãi biển Kỳ Co','Ky Co Beach']::text[], 'Bãi biển hoang sơ tuyệt đẹp với làn nước trong xanh hai màu và bãi cát vàng mịn màng.', 'Kỳ Co là một địa điểm du lịch Quy Nhơn nổi tiếng với thiên nhiên hoang sơ, hoàn toàn chưa bị các hoạt động dịch vụ du lịch làm phiền. Nơi đây có nhiều bãi cát vàng, dòng nước xanh trong, sóng biển khá yếu và êm ả, rất thích hợp để tắm biển và thư giãn.',
            'Xã Nhơn Lý, Quy Nhơn, Bình Định, Việt Nam', NULL, NULL, 'https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-2.jpg?tr=q-70,c-at_max,w-1000,h-600', 'https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-2.jpg?tr=q-70,c-at_max,w-1000,h-600', '[{"src": "https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-2.jpg?tr=q-70,c-at_max,w-1000,h-600", "alt": "Kỳ Co"}]'::jsonb, NULL, NULL,
            NULL, '{"features": ["Bãi cát vàng", "Nước biển trong xanh", "Sóng êm"]}'::jsonb, '{"tags": ["Bãi biển", "Hoang sơ", "Tắm biển", "Nghỉ dưỡng"], "sentiment": "Very positive", "best_time_to_visit": "Mùa hè", "suitable_for": ["Gia đình", "Nhóm bạn", "Trẻ em"]}'::jsonb, '{"urls": ["https://www.traveloka.com/vi-vn/explore/destination/dia-diem-du-lich-quy-nhon-2/143408"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn"], "titles": ["15 địa điểm du lịch Quy Nhơn bạn không thể bỏ lỡ - Traveloka"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'f5407781-07d1-42a8-8b5a-09f22986aac9', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Đồi cát Phương Mai', ARRAY['Phuong Mai Sand Dunes']::text[], 'Đồi cát rộng lớn được ví như ''Sahara thu nhỏ'' của Quy Nhơn, lý tưởng cho hoạt động trượt cát và ngắm hoàng hôn.', 'Đồi Cát Phương Mai là một trong những đồi cát hoang sơ và đẹp nhất của tỉnh Bình Định. Với những triền cát trắng mịn trải dài mênh mông, nơi đây mang lại không khí đậm chất miền Trung nắng gió và là điểm dừng chân tuyệt vời để chụp ảnh check-in trên đường trở về Quy Nhơn.',
            'Bán đảo Phương Mai, Quy Nhơn, Bình Định, Việt Nam', NULL, NULL, 'https://ik.imagekit.io/tvlk/blog/2022/06/dia-diem-du-lich-quy-nhon-3-1024x603.jpg?tr=q-70,c-at_max,w-1000,h-600', 'https://ik.imagekit.io/tvlk/blog/2022/06/dia-diem-du-lich-quy-nhon-3-1024x603.jpg?tr=q-70,c-at_max,w-1000,h-600', '[{"src": "https://ik.imagekit.io/tvlk/blog/2022/06/dia-diem-du-lich-quy-nhon-3-1024x603.jpg?tr=q-70,c-at_max,w-1000,h-600", "alt": "địa điểm du lịch Quy Nhơn"}, {"src": "https://cdn.xanhsm.com/2024/12/4b11686a-bai-bien-quy-nhon-13.jpg", "alt": "Đồi cát Phương Mai với những cồn cát trắng xóa"}]'::jsonb, NULL, NULL,
            8.0, '{"activities": ["Trượt cát", "Chụp ảnh", "Ngắm cảnh"], "altitude": "100m", "landscape": "Đồi cát trắng, trời xanh, view hướng biển"}'::jsonb, '{"tags": ["Đồi cát", "Trượt cát", "Check-in", "Hoang mạc", "sa mạc", "phương mai", "chụp ảnh", "Chụp ảnh check-in", "Cảnh quan thiên nhiên"], "sentiment": "Positive", "best_time_to_visit": "Sáng sớm hoặc chiều muộn để tránh nắng gắt", "suitable_for": ["Giới trẻ", "Người thích phiêu lưu", "Nhóm bạn", "chụp ảnh", "phượt thủ", "Nhiếp ảnh gia", "Khách du lịch tự túc"]}'::jsonb, '{"urls": ["https://www.traveloka.com/vi-vn/explore/destination/dia-diem-du-lich-quy-nhon-2/143408", "https://www.greensm.com/vn-vi/news/bai-bien-quy-nhon", "https://cuongdulich.com/dia-diem/2803-kinh-nghiem-du-lich-ky-co-eo-gio.html"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn", "bãi biển đẹp hoang sơ ở Quy Nhơn", "Kỳ Co Eo Gió Quy Nhơn có gì chơi"], "titles": ["15 địa điểm du lịch Quy Nhơn bạn không thể bỏ lỡ - Traveloka", "Review Top 10 bãi biển đẹp nhất Quy Nhơn | Green SM", "Kinh nghiệm du lịch Kỳ Co - Eo Gió trong 1 ngày chi tiết nhất có kèm ..."]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Cù Lao Xanh', ARRAY['Đảo Nhơn Châu','Blue Island']::text[], 'Hòn đảo hoang sơ được mệnh danh là ''viên ngọc thô'' của Quy Nhơn với làn nước biển xanh ngắt.', 'Cù Lao Xanh là một hải đảo giữ được trọn vẹn vẻ hoang sơ mộc mạc. Nơi đây sở hữu làn nước xanh trong tận đáy, sóng biển êm đềm và bờ cát trắng trải dài. Du khách có thể tắm biển, tổ chức tiệc nướng hải sản và tham gia nhiều hoạt động trải nghiệm biển thú vị.',
            'Xã Nhơn Châu, Quy Nhơn, Bình Định, Việt Nam', NULL, NULL, 'https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-3.jpg?tr=q-70,c-at_max,w-1000,h-600', 'https://ik.imagekit.io/tvlk/blog/2022/09/cu-lao-xanh-cover.jpg?tr=q-70,h-250,w-250', '[{"src": "https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-3.jpg?tr=q-70,c-at_max,w-1000,h-600", "alt": "Cù Lao Xanh"}, {"src": "https://ik.imagekit.io/tvlk/blog/2022/09/cu-lao-xanh-cover.jpg?tr=q-70,h-250,w-250", "alt": "Cù Lao Xanh"}, {"src": "https://cdn.xanhsm.com/2024/12/92b7e3a9-bai-bien-quy-nhon-10.jpg", "alt": "Cù Lao Xanh với nước biển trong xanh như ngọc bích"}]'::jsonb, NULL, NULL,
            NULL, '{"activities": ["Tắm biển", "Cắm trại", "Thưởng thức hải sản", "Tiệc nướng BBQ"], "distance_from_shore": "24km"}'::jsonb, '{"tags": ["Hải đảo", "Hoang sơ", "Cắm trại", "Hải sản", "hòn ngọc viễn đông", "nhơn châu", "san hô", "hệ sinh thái biển"], "sentiment": "Very positive", "best_time_to_visit": "Mùa khô", "suitable_for": ["Người thích khám phá", "Phượt thủ", "Nhóm bạn", "khám phá", "người yêu thiên nhiên"]}'::jsonb, '{"urls": ["https://www.traveloka.com/vi-vn/explore/destination/dia-diem-du-lich-quy-nhon-2/143408", "https://www.greensm.com/vn-vi/news/bai-bien-quy-nhon"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn", "bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["15 địa điểm du lịch Quy Nhơn bạn không thể bỏ lỡ - Traveloka", "Review Top 10 bãi biển đẹp nhất Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Hòn Khô', ARRAY['Đảo Hòn Khô','Làng chài Nhơn Hải']::text[], 'Đảo nhỏ yên bình thuộc xã Nhơn Hải, nổi tiếng với con đường xuyên biển độc đáo và rặng san hô rực rỡ.', 'Hòn Khô là một hòn đảo bình yên với sóng biển vỗ nhẹ cùng làn nước trong xanh. Đến đây, du khách có thể trải nghiệm tắm biển, lặn ngắm san hô dưới lòng đại dương, chinh phục các dãy núi đá bí ẩn hay khám phá con đường đi bộ dưới biển đầy ấn tượng.',
            'Xã Nhơn Hải, Quy Nhơn, Bình Định, Việt Nam', NULL, NULL, 'https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-5.jpg?tr=q-70,c-at_max,w-1000,h-600', 'https://ik.imagekit.io/tvlk/blog/2023/04/hon-kho-cover-mobile.png?tr=q-70,h-250,w-250', '[{"src": "https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-5.jpg?tr=q-70,c-at_max,w-1000,h-600", "alt": "Hòn Khô"}, {"src": "https://ik.imagekit.io/tvlk/blog/2023/04/hon-kho-cover-mobile.png?tr=q-70,h-250,w-250", "alt": "Hòn Khô"}, {"src": "https://cdn.xanhsm.com/2024/12/71ea68c9-bai-bien-quy-nhon-5.jpg", "alt": "Hòn Khô với vẻ đẹp hoang sơ, yên bình"}]'::jsonb, NULL, NULL,
            NULL, '{"activities": ["Lặn ngắm san hô", "Đi bộ xuyên biển", "Tắm biển"], "distance_from_shore": "16km"}'::jsonb, '{"tags": ["Đảo", "Lặn san hô", "Làng chài", "Yên bình", "đảo hoang sơ", "nhơn hải", "thiên nhiên"], "sentiment": "Positive", "best_time_to_visit": "Tháng 3 đến tháng 9", "suitable_for": ["Gia đình", "Cặp đôi", "Người yêu thiên nhiên", "khám phá", "tránh ồn ào"]}'::jsonb, '{"urls": ["https://www.traveloka.com/vi-vn/explore/destination/dia-diem-du-lich-quy-nhon-2/143408", "https://www.greensm.com/vn-vi/news/bai-bien-quy-nhon"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn", "bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["15 địa điểm du lịch Quy Nhơn bạn không thể bỏ lỡ - Traveloka", "Review Top 10 bãi biển đẹp nhất Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Tịnh xá Ngọc Hòa', ARRAY['Ngoc Hoa Monastery']::text[], 'Ngôi tịnh xá thanh tịnh tọa lạc bên bờ biển Nhơn Lý với địa thế tựa lưng vào núi, hướng mặt ra đại dương.', 'Được xây dựng từ những năm 1960 bởi cố Đức thầy Thích Giác An, Tịnh xá Ngọc Hòa sở hữu địa thế tuyệt đẹp dựa lưng vào núi, bên cạnh là đại dương rì rào sóng vỗ. Nơi đây mang bầu không khí vô cùng yên bình, tĩnh lặng, thu hút nhiều tín đồ Phật giáo và du khách ghé thăm hàng năm.',
            'Xã Nhơn Lý, Quy Nhơn, Bình Định, Việt Nam', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/90f26dba-chua-quy-nhon-3-820x1024.jpg', 'https://cdn.xanhsm.com/2024/12/90f26dba-chua-quy-nhon-3-820x1024.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/90f26dba-chua-quy-nhon-3-820x1024.jpg", "alt": "Tịnh xá Ngọc Hòa với tượng Phật Quan Thế Âm Bồ Tát hai mặt cao lớn"}]'::jsonb, NULL, NULL,
            8.2, '{"highlights": ["Tượng Phật đôi Quan Thế Âm", "Tượng Quan Thế Âm Bồ Tát hai mặt cao nhất Việt Nam", "Ngắm toàn cảnh vịnh biển từ trên cao"], "special_feature": "Tượng đôi Phật Bà Quan Âm cao nhất Việt Nam", "founded_year": "1960", "founder": "Thích Giác An"}'::jsonb, '{"tags": ["Tâm linh", "Chùa chiền", "Tịnh xá", "Văn hóa", "Điểm tham quan văn hóa", "View biển", "Yên bình", "Nhơn Lý", "Ngắm cảnh biển"], "sentiment": "Positive", "best_time_to_visit": "Quanh năm", "suitable_for": ["Người lớn tuổi", "Gia đình", "Du khách hành hương", "Khách hành hương", "Người tìm kiếm sự thanh tịnh", "Người tìm kiếm sự yên tĩnh", "Khách du lịch Nhơn Lý", "Khách du lịch tâm linh", "Người thích ngắm cảnh"]}'::jsonb, '{"urls": ["https://www.traveloka.com/vi-vn/explore/destination/dia-diem-du-lich-quy-nhon-2/143408", "https://cuongdulich.com/dia-diem/2803-kinh-nghiem-du-lich-ky-co-eo-gio.html", "https://dulichvietdu.com.vn/cac-ngoi-chua-o-quy-nhon-noi-tieng/", "https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn", "Kỳ Co Eo Gió Quy Nhơn có gì chơi", "chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["15 địa điểm du lịch Quy Nhơn bạn không thể bỏ lỡ - Traveloka", "Kinh nghiệm du lịch Kỳ Co - Eo Gió trong 1 ngày chi tiết nhất có kèm ...", "Gợi ý 15+ ngôi chùa ở Quy Nhơn nổi tiếng", "Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
