            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'b192353b-66e4-473b-877b-ad7e3a4e891d', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Tháp đôi Quy Nhơn', ARRAY['Tháp Đôi','Tháp Hưng Thạnh']::text[], 'Di tích tháp Chăm độc đáo nằm ngay giữa trung tâm thành phố Quy Nhơn, mang đậm dấu ấn văn hóa Chăm Pa cổ.', 'Tháp Đôi Quy Nhơn được xây dựng từ cuối thế kỷ XII đến đầu thế kỷ XIII, mang phong cách nghệ thuật giao thoa giữa tháp Chăm Bình Định và nghệ thuật Khmer thời Angkor Vat - Bayon. Tháp gồm hai ngọn tháp lớn nhỏ nằm kề nhau, được xây dựng bằng gạch nung xếp khít tỉ mỉ. Khuôn viên tháp rộng rãi, rợp bóng cây xanh, rất thuận tiện cho du khách ghé thăm và tìm hiểu lịch sử.',
            'Phường Đống Đa, Quy Nhơn, Bình Định, Việt Nam', NULL, NULL, 'https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-4.jpg?tr=q-70,c-at_max,w-1000,h-600', 'https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-4.jpg?tr=q-70,c-at_max,w-1000,h-600', '[{"src": "https://ik.imagekit.io/tvlk/blog/2024/07/dia-diem-du-lich-quy-nhon-4.jpg?tr=q-70,c-at_max,w-1000,h-600", "alt": "Tháp đôi Quy Nhơn"}, {"src": "https://quynhontourist.vn/wp-content/uploads/2017/11/du-lich-quy-nhon-3-ngay-2-dem-quynhontourist-3.jpg", "alt": "Khách hàng Quy Nhơn Tourist check in tại Tháp Đôi Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon2.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon3.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon4.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon5.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon6.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"architecture": "Chăm Pa, Angkor", "ticket_price": "8.000đ/người", "opening_hours": "08:00 - 19:00"}'::jsonb, '{"tags": ["Di tích lịch sử", "Văn hóa Chăm", "Kiến trúc cổ", "Check-in", "Tháp Chăm", "Chăm Pa"], "sentiment": "Positive", "best_time_to_visit": "Quanh năm", "suitable_for": ["Người thích lịch sử", "Khách du lịch tự túc", "Gia đình", "Người thích tìm hiểu lịch sử", "Khách du lịch", "Chụp ảnh check-in", "Người yêu lịch sử"], "notes": "Nằm ngay trung tâm thành phố nên rất dễ di chuyển. Đối diện có quán ăn Anh Nhật Gia Viên nổi tiếng."}'::jsonb, '{"urls": ["https://www.traveloka.com/vi-vn/explore/destination/dia-diem-du-lich-quy-nhon-2/143408", "https://quynhontourist.vn/trong-noi-thanh-quy-nhon-co-nhung-diem-du-lich-nao/", "https://cattour.vn/blog/nhung-ngon-thap-cham-quy-nhon-binh-dinh-2071.html"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn", "tháp chàm nổi tiếng ở Quy Nhơn Bình Định"], "titles": ["15 địa điểm du lịch Quy Nhơn bạn không thể bỏ lỡ - Traveloka", "TRONG NỘI THÀNH QUY NHƠN có những ĐIỂM DU LỊCH NÀO? - Quy Nhơn Tourist", "Những ngọn tháp Chăm Quy Nhơn Bình Định - điểm đến sống ảo, khám phá văn hóa đặc sắc"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'f5407781-07d1-42a8-8b5a-09f22986aac9', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Khu du lịch Ghềnh Ráng – Tiên Sa', ARRAY['Ghềnh Ráng - Tiên Sa']::text[], 'Khu du lịch nổi tiếng nằm ở cuối đường bờ biển Quy Nhơn, nơi ngắm toàn cảnh thành phố tuyệt đẹp.', 'Đây là điểm du lịch hầu hết tất cả các khách du lịch đều ghé thăm mỗi khi đến Quy Nhơn. Nằm ở cuối đường bờ biển của thành phố, nơi mà du khách có thể thấy toàn cảnh đường bờ biển dài, cong tuyệt đẹp của thành phố Quy Nhơn.',
            'Cuối đường bờ biển Quy Nhơn, Thành phố Quy Nhơn, Bình Định', NULL, NULL, 'https://quynhontourist.vn/wp-content/uploads/2017/09/ghenh-rang-tien-sa-ngay-doi-moi.jpg', 'https://quynhontourist.vn/wp-content/uploads/2017/09/ghenh-rang-tien-sa-ngay-doi-moi.jpg', '[{"src": "https://quynhontourist.vn/wp-content/uploads/2017/09/ghenh-rang-tien-sa-ngay-doi-moi.jpg", "alt": "Thành phố Quy Nhơn nhìn từ Ghềnh Ráng – Tiên Sa"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Khu du lịch", "Ngắm cảnh", "Bờ biển"], "sentiment": "Positive", "best_time_to_visit": "Chiều tà hoặc sáng sớm", "suitable_for": ["Gia đình", "Cặp đôi", "Đoàn khách du lịch"]}'::jsonb, '{"urls": ["https://quynhontourist.vn/trong-noi-thanh-quy-nhon-co-nhung-diem-du-lich-nao/"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn"], "titles": ["TRONG NỘI THÀNH QUY NHƠN có những ĐIỂM DU LỊCH NÀO? - Quy Nhơn Tourist"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'b192353b-66e4-473b-877b-ad7e3a4e891d', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Mộ Hàn Mặc Tử', ARRAY['Khu mộ nhà thơ Hàn Mặc Tử']::text[], 'Nơi an nghỉ của nhà thơ tài hoa Hàn Mặc Tử nằm trong khu du lịch Ghềnh Ráng.', 'Nơi viếng thăm mộ nhà thơ Hàn Mặc Tử, chụp hình tại Vườn Thơ, nơi mà mỗi năm đều có các nhà thơ trên toàn quốc tập trung về đây để đối ẩm. Du khách cũng có thể ghé Bút Lửa Zũ Kha để nghe đọc thơ Hàn và mua quà lưu niệm.',
            'Khu du lịch Ghềnh Ráng – Tiên Sa, Thành phố Quy Nhơn, Bình Định', NULL, NULL, 'https://quynhontourist.vn/wp-content/uploads/2017/09/tour-du-lich-quy-nhon-phu-yen-2-ngay-1-dem.jpg', 'https://quynhontourist.vn/wp-content/uploads/2017/09/tour-du-lich-quy-nhon-phu-yen-2-ngay-1-dem.jpg', '[{"src": "https://quynhontourist.vn/wp-content/uploads/2017/09/tour-du-lich-quy-nhon-phu-yen-2-ngay-1-dem.jpg", "alt": "Bút lửa Zũ Kha – Người giữ lửa cho Thơ Hàn"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Di tích lịch sử", "Văn học", "Tâm linh"], "sentiment": "Positive", "best_time_to_visit": "Ban ngày", "suitable_for": ["Người yêu thơ ca", "Người lớn tuổi", "Khách hành hương"]}'::jsonb, '{"urls": ["https://quynhontourist.vn/trong-noi-thanh-quy-nhon-co-nhung-diem-du-lich-nao/"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn"], "titles": ["TRONG NỘI THÀNH QUY NHƠN có những ĐIỂM DU LỊCH NÀO? - Quy Nhơn Tourist"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi tắm Hoàng Hậu', ARRAY['Bãi Đá Trứng','Bãi Trứng','Queen''s Beach']::text[], 'Bãi tắm độc đáo với vô số hòn đá tròn như trứng chim khổng lồ nằm xếp chồng lên nhau.', 'Nằm trong khu du lịch Ghềnh Ráng Tiên Sa, bãi tắm Hoàng Hậu từng là nơi nghỉ dưỡng yêu thích của Nam Phương Hoàng hậu. Nơi đây nổi tiếng với những viên đá tròn nhẵn như trứng chim khổng lồ và sóng biển xô bờ tung bọt trắng xóa.',
            'Khu du lịch Ghềnh Ráng – Tiên Sa, Thành phố Quy Nhơn, Bình Định', NULL, NULL, 'https://quynhontourist.vn/wp-content/uploads/2018/02/bai-tam-hoang-hau-ghenh-rang-tien-sa-quy-nhon-tourist.jpg', 'https://quynhontourist.vn/wp-content/uploads/2018/02/bai-tam-hoang-hau-ghenh-rang-tien-sa-quy-nhon-tourist.jpg', '[{"src": "https://quynhontourist.vn/wp-content/uploads/2018/02/bai-tam-hoang-hau-ghenh-rang-tien-sa-quy-nhon-tourist.jpg", "alt": "Bãi tắm Hoàng Hậu tại Khu du lịch Ghềnh Ráng Tiên Sa"}, {"src": "https://cdn.xanhsm.com/2024/12/8259bae6-bai-bien-quy-nhon-2.jpg", "alt": "Bãi tắm Hoàng Hậu với biển xanh biếc"}, {"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-4-1760493903.jpg", "alt": "Bãi tắm Hoàng Hậu Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"distance_from_center": "3km", "features": ["Đá tròn như trứng", "Ghềnh đá cao"]}'::jsonb, '{"tags": ["Bãi biển", "Check-in", "Địa điểm độc đáo", "hoang sơ", "ghềnh ráng", "bãi trứng", "Unique Beach", "Geological Wonder", "Historical Connection"], "sentiment": "Positive", "best_time_to_visit": "Sáng sớm hoặc chiều mát", "suitable_for": ["Người thích chụp ảnh", "Gia đình", "Cặp đôi", "người yêu thiên nhiên", "chụp ảnh", "khám phá", "Sightseeing", "History lovers", "Families"]}'::jsonb, '{"urls": ["https://quynhontourist.vn/trong-noi-thanh-quy-nhon-co-nhung-diem-du-lich-nao/", "https://www.greensm.com/vn-vi/news/bai-bien-quy-nhon", "https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn", "bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["TRONG NỘI THÀNH QUY NHƠN có những ĐIỂM DU LỊCH NÀO? - Quy Nhơn Tourist", "Review Top 10 bãi biển đẹp nhất Quy Nhơn | Green SM", "Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'b192353b-66e4-473b-877b-ad7e3a4e891d', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Trại Phong Quy Hòa', ARRAY['Làng phong Quy Hòa','Bệnh viện Phong - Da liễu Trung ương Quy Hòa']::text[], 'Ngôi làng yên bình ven biển, nơi nhà thơ Hàn Mặc Tử đã sống những ngày cuối đời.', 'Cách Khu du lịch Ghềnh Ráng Tiên Sa khoảng 3 km, Trại Phong Quy Hòa nằm yên bình giữa làng chài ven biển. Đến đây, du khách sẽ cảm nhận được không gian mát mẻ, yên bình, ghé thăm nhà lưu niệm của nhà thơ Hàn Mặc Tử.',
            'Quy Hòa, Ghềnh Ráng, Thành phố Quy Nhơn, Bình Định', NULL, NULL, 'https://quynhontourist.vn/wp-content/uploads/2018/02/trai-phong-quy-hoa-tuyet-dep-quy-nhon-tourist.jpg', 'https://quynhontourist.vn/wp-content/uploads/2018/02/trai-phong-quy-hoa-tuyet-dep-quy-nhon-tourist.jpg', '[{"src": "https://quynhontourist.vn/wp-content/uploads/2018/02/trai-phong-quy-hoa-tuyet-dep-quy-nhon-tourist.jpg", "alt": "Phong cảnh yên bình của Trại Phong Quy Hòa"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Làng chài", "Di tích lịch sử", "Yên bình"], "sentiment": "Positive", "best_time_to_visit": "Sáng hoặc chiều mát", "suitable_for": ["Người thích sự yên tĩnh", "Khách du lịch văn hóa"]}'::jsonb, '{"urls": ["https://quynhontourist.vn/trong-noi-thanh-quy-nhon-co-nhung-diem-du-lich-nao/"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn"], "titles": ["TRONG NỘI THÀNH QUY NHƠN có những ĐIỂM DU LỊCH NÀO? - Quy Nhơn Tourist"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
