INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'e643bfac-efb6-4888-905c-cb3662363482', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Nhà Thờ Chánh Tòa Quy Nhơn', ARRAY['Nhà Thờ Nhọn']::text[], 'Nhà thờ cổ kính nổi tiếng nằm ngay trung tâm thành phố Quy Nhơn.', 'Một trong những công trình kiến trúc tôn giáo đẹp mắt và lâu đời, là điểm tham quan thu hút du khách khi đến nội thành Quy Nhơn.',
            '122 Trần Hưng Đạo, Hải Cảng, Thành phố Quy Nhơn, Bình Định', NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Nhà thờ", "Kiến trúc Gothic", "Tôn giáo"], "sentiment": "Positive", "best_time_to_visit": "Ban ngày", "suitable_for": ["Khách du lịch", "Người theo đạo Thiên Chúa"]}'::jsonb, '{"urls": ["https://quynhontourist.vn/trong-noi-thanh-quy-nhon-co-nhung-diem-du-lich-nao/"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn"], "titles": ["TRONG NỘI THÀNH QUY NHƠN có những ĐIỂM DU LỊCH NÀO? - Quy Nhơn Tourist"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
