INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Long Khánh', ARRAY['Chùa Long Khánh Quy Nhơn']::text[], 'Ngôi chùa cổ kính với niên đại hơn 300 năm, là một trong những trung tâm Phật giáo lớn nhất tại Bình Định.', 'Chùa Long Khánh được xây dựng cách đây hơn 300 năm và đã trải qua nhiều biến cố lịch sử cùng các đợt trùng tu lớn. Hiện nay, chùa vẫn lưu giữ quả chuông đồng cổ được đúc từ thời vua Gia Long thứ 4 (năm 1805). Đây là điểm đến tâm linh quen thuộc của người dân địa phương và du khách, đồng thời cũng là nơi thường xuyên tổ chức các khóa tu mùa hè ý nghĩa cho giới trẻ.',
            '141 Trần Cao Vân, Lê Lợi, Thành phố Quy Nhơn, Bình Định', NULL, NULL, 'https://dulichvietdu.com.vn/wp-content/uploads/2023/08/Chua-o-Quy-Nhon-noi-tieng-2.png', 'https://dulichvietdu.com.vn/wp-content/uploads/2023/08/Chua-o-Quy-Nhon-noi-tieng-2.png', '[{"src": "https://dulichvietdu.com.vn/wp-content/uploads/2023/08/Chua-o-Quy-Nhon-noi-tieng-2.png", "alt": "Chùa Long Khánh Quy Nhơn"}, {"src": "https://cdn.xanhsm.com/2024/12/54f4cd4a-chua-quy-nhon-6.jpg", "alt": "Chùa Long Khánh với kiến trúc cổ kính, trang nghiêm"}]'::jsonb, NULL, NULL,
            NULL, '{"historical_significance": "Hơn 300 năm tuổi", "relics": "Quả chuông đồng đúc năm 1805 thời vua Gia Long"}'::jsonb, '{"tags": ["Chùa", "Tâm linh", "Cổ kính", "Chùa cổ", "Lịch sử", "Khóa tu mùa hè", "Trung tâm thành phố", "Thời nhà Nguyễn"], "sentiment": "Positive", "best_time_to_visit": "Sáng sớm", "suitable_for": ["Người lớn tuổi", "Khách hành hương", "Gia đình", "Người thích tìm hiểu lịch sử", "Khách du lịch", "Người đi lễ chùa"]}'::jsonb, '{"urls": ["https://quynhontourist.vn/trong-noi-thanh-quy-nhon-co-nhung-diem-du-lich-nao/", "https://dulichvietdu.com.vn/cac-ngoi-chua-o-quy-nhon-noi-tieng/", "https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn", "chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["TRONG NỘI THÀNH QUY NHƠN có những ĐIỂM DU LỊCH NÀO? - Quy Nhơn Tourist", "Gợi ý 15+ ngôi chùa ở Quy Nhơn nổi tiếng", "Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
