            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'f5407781-07d1-42a8-8b5a-09f22986aac9', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Cầu Thị Nại', ARRAY['Cầu vượt biển Thị Nại','Cầu Nhơn Hội']::text[], 'Cây cầu vượt biển dài 2,5 km nối liền trung tâm thành phố Quy Nhơn với bán đảo Phương Mai.', 'Cầu Thị Nại từng là cây cầu vượt biển dài nhất Việt Nam, bắc qua đầm Thị Nại. Đây là điểm dừng chân lý tưởng để du khách ngắm nhìn cảnh biển xanh ngắt, cảnh người dân chài thả lưới và cảm nhận không khí mát rượi từ biển khơi.',
            'Cầu Thị Nại, Thành phố Quy Nhơn, Bình Định', NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, NULL,
            8.0, '{"length": "2.5 km", "historical_context": "Nơi diễn ra những trận thủy chiến lịch sử giữa Champa và Đại Việt, Tây Sơn và nhà Nguyễn"}'::jsonb, '{"tags": ["Cầu vượt biển", "Ngắm cảnh", "Check-in", "Ngắm bình minh", "Điểm check-in", "Lịch sử"], "sentiment": "Positive", "best_time_to_visit": "Chiều hoàng hôn", "suitable_for": ["Phượt thủ", "Khách du lịch", "Khách du lịch tự túc", "Người thích ngắm cảnh"]}'::jsonb, '{"urls": ["https://quynhontourist.vn/trong-noi-thanh-quy-nhon-co-nhung-diem-du-lich-nao/", "https://cuongdulich.com/dia-diem/2803-kinh-nghiem-du-lich-ky-co-eo-gio.html"], "queries": ["địa điểm du lịch nổi tiếng ở Quy Nhơn", "Kỳ Co Eo Gió Quy Nhơn có gì chơi"], "titles": ["TRONG NỘI THÀNH QUY NHƠN có những ĐIỂM DU LỊCH NÀO? - Quy Nhơn Tourist", "Kinh nghiệm du lịch Kỳ Co - Eo Gió trong 1 ngày chi tiết nhất có kèm ..."]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
