        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi tắm Quy Nhơn', ARRAY[]::text[], 'Nằm ngay trung tâm thành phố, bãi tắm Quy Nhơn luôn tấp nập và sôi động.', 'Bãi cát dài thoai thoải, nước biển trong xanh, thích hợp cho những ai thích tắm biển và tham gia các hoạt động thể thao trên biển.',
            'Trung tâm thành phố Quy Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/bc65b961-bai-bien-quy-nhon-1.jpg', 'https://cdn.xanhsm.com/2024/12/bc65b961-bai-bien-quy-nhon-1.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/bc65b961-bai-bien-quy-nhon-1.jpg", "alt": "Bãi tắm Quy Nhơn với dòng người tấp nập"}]'::jsonb, NULL, NULL,
