        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi biển Eo Gió', ARRAY['Eo Gió']::text[], 'Eo Gió là một eo biển nhỏ nằm giữa hai vách núi cao vút, thuộc xã Nhơn Lý, cách trung tâm thành phố khoảng 20km.', 'Nơi đây sở hữu cảnh quan hùng vĩ, nước biển trong xanh và những rặng san hô đa dạng.',
            'Xã Nhơn Lý, Quy Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/720b0c45-bai-bien-quy-nhon-3.jpg', 'https://cdn.xanhsm.com/2024/12/720b0c45-bai-bien-quy-nhon-3.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/720b0c45-bai-bien-quy-nhon-3.jpg", "alt": "Bãi biển Eo Gió với eo biển nhỏ và vách đá dốc đứng"}]'::jsonb, NULL, NULL,
            NULL, '{"distance_from_center": "20km"}'::jsonb, '{"tags": ["eo biển", "vách đá", "san hô", "nhơn lý"], "sentiment": "positive", "suitable_for": ["người yêu thiên nhiên", "chụp ảnh", "phượt thủ"]}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/bai-bien-quy-nhon"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Review Top 10 bãi biển đẹp nhất Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
