INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi biển Kỳ Co', ARRAY['Kỳ Co','Bãi Kỳ Co','Kỳ Co Beach','Bãi tắm Kỳ Co']::text[], 'Một trong những bãi tắm đẹp nhất Miền Trung với bờ cát trải dài cùng làn nước trong xanh 2 màu tuyệt đẹp.', 'Kỳ Co là một bãi biển hoang sơ tuyệt đẹp nằm ở xã Nhơn Lý, Quy Nhơn. Nơi đây nổi tiếng với làn nước biển trong vắt chia hai màu rõ rệt, bãi cát trắng mịn màng và các vách đá hùng vĩ bao quanh. Du khách đến đây có thể trải nghiệm đi cano siêu tốc, tắm biển, tham gia các trò chơi mạo hiểm dưới nước và thưởng thức hải sản tươi ngon.',
            'Xã Nhơn Lý, Quy Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/82f77079-bai-bien-quy-nhon-4.jpg', 'https://cdn.xanhsm.com/2024/12/82f77079-bai-bien-quy-nhon-4.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/82f77079-bai-bien-quy-nhon-4.jpg", "alt": "Bãi biển Kỳ Co với bãi cát trắng mịn và nước biển trong vắt"}, {"src": "https://cuongdulich.com/assets/posts/1614731116-bai-ky-co-1.JPG", "alt": "Bãi biển Kỳ Co trong xanh"}, {"src": "https://cuongdulich.com/assets/posts/1614731097-bai-ky-co-11.JPG", "alt": "Toàn cảnh bãi Kỳ Co"}, {"src": "https://cuongdulich.com/assets/posts/1614731224-bai-ky-co-12.JPG", "alt": "Khu du lịch Kỳ Co"}, {"src": "https://cuongdulich.com/assets/posts/1614731069-du-lich-ky-co-eo-gio.jpg", "alt": "Du lịch Kỳ Co Eo Gió"}, {"src": "https://dulichquynhon.blog/wp-content/uploads/2026/04/ky-co-eo-gio-3.webp", "alt": "Một số địa điểm check-in được yêu thích tại Kỳ Co Beach"}, {"src": "https://dulichquynhon.blog/wp-content/uploads/2026/04/ky-co-eo-gio-2.webp", "alt": "Du khách có thể di chuyển đến Kỳ Co bằng tàu"}, {"src": "https://dulichquynhon.blog/wp-content/uploads/2026/04/ky-co-eo-gio-5.webp", "alt": "Khoảnh khắc hoàng hôn rực rỡ tại bãi biển"}]'::jsonb, NULL, NULL,
            9.5, '{"distance_from_center": "25km", "transportation": "Cano từ bến Nhơn Lý hoặc đường bộ qua cổng khu du lịch Hoàng Đạt", "ticket_prices": {"shuttle_bus_from_peak": "100.000 VND/người/khứ hồi", "electric_car_from_base": "200.000 VND/người/khứ hồi"}, "water_sports_prices": {"sea_walking": "1.000.000 VND/người/20 phút", "snorkeling": "250.000 VND/người/lần", "jet_ski": "600.000 VND/15 phút", "parasailing_single": "600.000 VND/vòng", "parasailing_double": "900.000 VND/vòng", "banana_boat": "800.000 VND/10 phút", "kayak": "300.000 VND/60 phút"}, "ticket_price": "100.000 – 120.000 VNĐ/người (vé vào cổng bãi tắm và cầu gỗ), xe trung chuyển khứ hồi xuống bãi tắm: 50.000 VNĐ/người", "water_sports": ["Mô tô nước (Jetski): 400.000 - 700.000 VNĐ", "Cano kéo dù bay: 500.000 - 1.050.000 VNĐ", "Cano kéo phao chuối: 900.000 VNĐ/10 phút", "Cano kéo lướt ván: 900.000 VNĐ/10 phút"], "shower_price": "10.000 – 20.000 VNĐ/lượt tắm nước ngọt"}'::jsonb, '{"tags": ["maldives việt nam", "cát trắng", "nước trong xanh", "nhơn lý", "Bãi biển", "Lặn ngắm san hô", "Trò chơi dưới nước", "Cảnh đẹp thiên nhiên", "Thể thao dưới nước", "Check-in", "Thiên nhiên"], "sentiment": "positive", "suitable_for": ["nghỉ dưỡng", "gia đình", "chụp ảnh", "Cặp đôi", "Nhóm bạn", "Người thích phiêu lưu", "Nhóm bạn trẻ"], "best_time_to_visit": "Mùa hè (từ tháng 3 đến tháng 9), tránh mùa mưa biển động"}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/bai-bien-quy-nhon", "https://cuongdulich.com/dia-diem/2803-kinh-nghiem-du-lich-ky-co-eo-gio.html", "https://dulichquynhon.blog/dia-diem-du-lich/ky-co-eo-gio/"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn", "Kỳ Co Eo Gió Quy Nhơn có gì chơi"], "titles": ["Review Top 10 bãi biển đẹp nhất Quy Nhơn | Green SM", "Kinh nghiệm du lịch Kỳ Co - Eo Gió trong 1 ngày chi tiết nhất có kèm ...", "Du Lịch Kỳ Co - Eo Gió: Đường Đi, Giá Vé và Review Chi Tiết"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
