        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi Xép', ARRAY['Bãi Xép Quy Nhơn','Làng chài Bãi Xép']::text[], 'Được Business Insider đánh giá là một trong 16 hòn ngọc bí ẩn của châu Á với vẻ đẹp thanh bình.', 'Bãi Xép là một bức tranh thủy mặc hữu tình với đồi núi xanh mướt, bãi cát trắng mịn và làn nước trong xanh ngọc bích. Du khách đến đây có thể trải nghiệm cuộc sống chài lưới bình dị cùng người dân địa phương.',
            'Quy Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/5d7d3268-bai-bien-quy-nhon-7.jpg', 'https://cdn.xanhsm.com/2024/12/5d7d3268-bai-bien-quy-nhon-7.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/5d7d3268-bai-bien-quy-nhon-7.jpg", "alt": "Bãi Xép with ghềnh đá và nước biển xanh trong"}, {"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-9-1760493908.jpg", "alt": "Bãi Xép Quy Nhơn"}]'::jsonb, NULL, NULL,
