INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi Bàu', ARRAY['Bãi Bầu']::text[], 'Bãi biển hoang sơ, nhộn nhịp với nhiều hoạt động thể thao biển hấp dẫn nằm giáp ranh Quy Nhơn.', 'Nằm cách trung tâm Quy Nhơn khoảng 20km về phía Nam, thuộc địa phận Sông Cầu (Phú Yên), Bãi Bàu sở hữu bãi cát trắng mịn, nước biển trong xanh và nhiều hoạt động giải trí như nhảy ghềnh, leo núi, lặn ngắm san hô.',
            'Khu du lịch Bãi Bàu, Quy Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/a2f47d1a-bai-bien-quy-nhon-8.jpg', 'https://cdn.xanhsm.com/2024/12/a2f47d1a-bai-bien-quy-nhon-8.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/a2f47d1a-bai-bien-quy-nhon-8.jpg", "alt": "Bãi Bàu với bãi cát trắng trải dài và hàng dừa xanh mát"}, {"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-8-1760493907.jpg", "alt": "Bãi Bàu Phú Yên Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"distance_from_center": "15km", "activities": ["Nhảy ghềnh", "Leo núi", "Lặn biển ngắm san hô"]}'::jsonb, '{"tags": ["khu du lịch", "cát trắng phẳng lì", "nghỉ dưỡng", "tắm biển", "Beach", "Outdoor Activities", "Recreation"], "sentiment": "positive", "suitable_for": ["gia đình", "nghỉ dưỡng", "nhóm bạn", "Groups", "Active travelers", "Families"]}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/bai-bien-quy-nhon", "https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Review Top 10 bãi biển đẹp nhất Quy Nhơn | Green SM", "Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi Bàng', ARRAY[]::text[], 'Nằm cách trung tâm thành phố khoảng 12km, Bãi Bàng là một bãi biển yên tĩnh, vắng vẻ, chưa được nhiều người biết đến.', 'Chưa được nhiều người biết đến, Bãi Bàng giữ nguyên vẻ đẹp tĩnh lặng, trong lành. Du khách có thể thỏa thích tắm biển, đi dạo hoặc nằm võng dưới bóng dừa, thưởng thức nước dừa ngọt lịm và lắng nghe tiếng sóng rì rào.',
            'Quy Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/20c1cdfb-bai-bien-quy-nhon-9.jpg', 'https://cdn.xanhsm.com/2024/12/20c1cdfb-bai-bien-quy-nhon-9.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/20c1cdfb-bai-bien-quy-nhon-9.jpg", "alt": "Bãi Bàng với vẻ đẹp hoang sơ, yên bình"}, {"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-11-1760493909.jpg", "alt": "Bãi Bàng Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"distance_from_center": "12km", "features": ["Rặng dừa cao vút", "Võng đơn sơ"]}'::jsonb, '{"tags": ["bãi biển yên tĩnh", "hàng dừa", "riêng tư", "vắng vẻ", "Beach", "Quiet", "Relaxing"], "sentiment": "positive", "suitable_for": ["người thích yên tĩnh", "cặp đôi", "thư giãn", "Relaxation", "Solo travelers"]}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/bai-bien-quy-nhon", "https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Review Top 10 bãi biển đẹp nhất Quy Nhơn | Green SM", "Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
