        ) VALUES (
            'b192353b-66e4-473b-877b-ad7e3a4e891d', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Tháp Đôi', ARRAY['Tháp Đôi Quy Nhơn']::text[], 'Di tích lịch sử Chăm Pa cổ kính với kiến trúc độc đáo nằm ngay trung tâm thành phố Quy Nhơn.', 'Tháp Đôi là một trong những di tích kiến trúc văn hóa Chăm Pa đặc sắc, thu hút đông đảo du khách đến tham quan và tìm hiểu lịch sử.',
            'Trung tâm thành phố Quy Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/26479d53-bai-bien-quy-nhon-11.jpg', 'https://cdn.xanhsm.com/2024/12/26479d53-bai-bien-quy-nhon-11.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/26479d53-bai-bien-quy-nhon-11.jpg", "alt": "Tháp Đôi Quy Nhơn với kiến trúc Chămpa độc đáo"}, {"src": "https://cdn.xanhsm.com/2024/12/efbc19ef-chua-quy-nhon-14.jpg", "alt": "Tháp Đôi di tích Chăm Pa cổ kính với kiến trúc độc đáo"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["di tích lịch sử", "kiến trúc chăm pa", "trung tâm thành phố", "Văn hóa Chăm Pa", "Kiến trúc cổ"], "sentiment": "positive", "suitable_for": ["người yêu lịch sử", "chụp ảnh", "gia đình", "Khách du lịch văn hóa"]}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/bai-bien-quy-nhon", "https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn", "chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Review Top 10 bãi biển đẹp nhất Quy Nhơn | Green SM", "Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
