            'Tuy Phước, Quy Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/246c92ed-bai-bien-quy-nhon-12.jpg', 'https://cdn.xanhsm.com/2024/12/246c92ed-bai-bien-quy-nhon-12.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/246c92ed-bai-bien-quy-nhon-12.jpg", "alt": "Tháp Bánh Ít với kiến trúc độc đáo"}]'::jsonb, NULL, NULL,
