            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi biển Quy Nhơn', ARRAY['Bãi tắm Quy Nhơn','Bãi biển vầng trăng khuyết']::text[], 'Bãi biển hình vầng trăng khuyết độc đáo kéo dài khoảng 5km ngay trung tâm thành phố Quy Nhơn.', 'Tọa lạc ngay trung tâm thành phố, bãi biển Quy Nhơn sở hữu làn nước trong xanh cùng bãi cát trắng trải dài từ Mũi Tấn đến Ghềnh Ráng Tiên Sa, tạo nên một hình trăng khuyết đầy thơ mộng.',
            'Trung tâm thành phố Quy Nhơn, Bình Định', NULL, NULL, 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-1-1760493903.jpg', 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-1-1760493903.jpg', '[{"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-1-1760493903.jpg", "alt": "Bãi biển Quy Nhơn hình trăng khuyết độc đáo"}]'::jsonb, NULL, NULL,
            NULL, '{"length": "5km"}'::jsonb, '{"tags": ["Beach", "City Beach", "Scenic"], "sentiment": "Positive", "suitable_for": ["Families", "Couples", "Solo travelers"]}'::jsonb, '{"urls": ["https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
