        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Biển Kỳ Co', ARRAY['Bãi tắm Kỳ Co','Kỳ Co Quy Nhơn']::text[], 'Bãi biển hoang sơ tuyệt đẹp với làn nước trong xanh và sóng êm, được che chở bởi hai dãy núi đá lớn.', 'Kỳ Co là một trong những bãi biển đẹp nhất Quy Nhơn, nổi bật với vẻ đẹp mộc mạc, bình dị và hoang sơ. Nhờ được bao bọc bởi núi đá, sóng biển ở đây rất êm, thích hợp cho các hoạt động tắm biển và thư giãn.',
            'Nhơn Lý, Quy Nhơn, Bình Định', NULL, NULL, 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-2-1760493903.jpg', 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-2-1760493903.jpg', '[{"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-2-1760493903.jpg", "alt": "Biển Kỳ Co Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"features": ["Hoang sơ", "Sóng êm", "Nước trong xanh"]}'::jsonb, '{"tags": ["Beach", "Nature", "Pristine"], "sentiment": "Very Positive", "suitable_for": ["Adventure seekers", "Nature lovers", "Families"]}'::jsonb, '{"urls": ["https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
