        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Biển Hòn Khô', ARRAY['Cù lao Hòn Khô','Đảo Hòn Khô']::text[], 'Đảo nhỏ hoang sơ với làn nước trong vắt nhìn thấy đáy và rặng san hô rực rỡ sắc màu.', 'Cách trung tâm Quy Nhơn khoảng 16km, Hòn Khô là điểm đến lý tưởng cho những ai yêu thích khám phá thiên nhiên hoang dã. Nơi đây sở hữu bãi biển trong xanh, sóng êm vào mùa lặng và những con sóng tung bọt trắng xóa vào mùa biển động.',
            'Nhơn Hải, Quy Nhơn, Bình Định', NULL, NULL, 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-5-1760493903.jpg', 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-5-1760493903.jpg', '[{"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-5-1760493903.jpg", "alt": "Biển Hòn Khô Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"distance_from_center": "16km"}'::jsonb, '{"tags": ["Island", "Coral Reef", "Pristine"], "sentiment": "Positive", "suitable_for": ["Snorkeling", "Adventure seekers", "Nature lovers"]}'::jsonb, '{"urls": ["https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
