        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Biển Cù Lao Xanh', ARRAY['Đảo Vân Phi']::text[], 'Hòn đảo biệt lập xanh ngắt với ngọn hải đăng cổ kính và nhịp sống làng chài bình dị.', 'Nằm giữa đại dương bao la, Cù Lao Xanh mang vẻ đẹp yên bình với sắc xanh của biển, trời và cây cối. Điểm nhấn của đảo là ngọn hải đăng cổ kính sừng sững và cuộc sống mộc mạc của ngư dân địa phương.',
            'Nhơn Châu, Quy Nhơn, Bình Định', NULL, NULL, 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-6-1760493903.jpg', 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-6-1760493903.jpg', '[{"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-6-1760493903.jpg", "alt": "Biển Cù Lao Xanh Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"highlights": ["Hải đăng cổ kính", "Làng chài bình dị"]}'::jsonb, '{"tags": ["Island", "Lighthouse", "Cultural Experience"], "sentiment": "Positive", "suitable_for": ["Explorers", "Solo travelers", "Photographers"]}'::jsonb, '{"urls": ["https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Biển Hòn Sẹo', ARRAY['Đảo Hòn Sẹo']::text[], 'Hòn đảo nhỏ hoang sơ sở hữu hệ sinh thái biển trù phú và rặng san hô đa dạng sắc màu.', 'Hòn Sẹo là một hòn đảo nhỏ hầu như không có người sinh sống, giữ trọn vẹn nét hoang sơ kỳ vĩ. Nơi đây thu hút du khách nhờ làn nước trong vắt, rặng san hô tuyệt đẹp và các món hải sản tươi ngon.',
            'Nhơn Lý, Quy Nhơn, Bình Định', NULL, NULL, 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-7-1760493903.jpg', 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-7-1760493903.jpg', '[{"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-7-1760493903.jpg", "alt": "Biển Hòn Sẹo Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"features": ["Hệ sinh thái trù phú", "Rặng san hô đa dạng"]}'::jsonb, '{"tags": ["Island", "Coral Reef", "Seafood"], "sentiment": "Positive", "suitable_for": ["Snorkeling", "Adventure seekers"]}'::jsonb, '{"urls": ["https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
