        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi Dại', ARRAY[]::text[], 'Bãi biển hoang sơ, yên bình ẩn mình giữa lòng Ghềnh Ráng, cách trung tâm thành phố chỉ 3km.', 'Bãi Dại mang vẻ đẹp mộc mạc, tách biệt khỏi sự ồn ào của phố thị. Nơi đây nổi bật với những phiến đá muôn hình vạn trạng rải rác bên bờ biển và những con sóng xô bờ tung bọt nước trắng xóa.',
            'Ghềnh Ráng, Quy Nhơn, Bình Định', NULL, NULL, 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-10-1760493909.jpg', 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-10-1760493909.jpg', '[{"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-10-1760493909.jpg", "alt": "Bãi Dại Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"distance_from_center": "3km"}'::jsonb, '{"tags": ["Beach", "Quiet", "Pristine"], "sentiment": "Positive", "suitable_for": ["Solo travelers", "Peace seekers"]}'::jsonb, '{"urls": ["https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
