        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi biển Nhơn Hải', ARRAY['Làng chài Nhơn Hải']::text[], 'Bãi biển thanh bình mang dáng hình cánh én tung bay với làn nước trong xanh và bãi cát trắng phau.', 'Cách trung tâm thành phố hơn 20km, bãi biển Nhơn Hải uốn lượn như cánh én, được bao bọc bởi các phiến đá và núi cao sừng sững. Nơi đây mang vẻ đẹp bình dị của một làng chài ngoại ô yên ả.',
            'Nhơn Hải, Quy Nhơn, Bình Định', NULL, NULL, 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-12-1760493910.jpg', 'https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-12-1760493910.jpg', '[{"src": "https://mia.vn/media/uploads/blog-du-lich/bai-bien-quy-nhon-12-1760493910.jpg", "alt": "Bãi biển Nhơn Hải"}, {"src": "https://mia.vn/media/uploads/blog-du-lich/lang-chai-nhon-hai-ve-dep-binh-di-noi-ngoai-o-thanh-pho-1679910798.jpg", "alt": "Làng chài Nhơn Hải"}]'::jsonb, NULL, NULL,
            NULL, '{"distance_from_center": "hơn 20km"}'::jsonb, '{"tags": ["Beach", "Fishing Village", "Scenic"], "sentiment": "Positive", "suitable_for": ["Families", "Couples", "Cultural explorers"]}'::jsonb, '{"urls": ["https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
