        ) VALUES (
            '11686bce-c7ba-4966-9de9-23f9e50ca18d', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Trung tâm Khám phá Khoa học Quy Nhơn', ARRAY['Explorascience Quy Nhon']::text[], 'Tọa độ khám phá khoa học và vũ trụ đầy thú vị dành cho mọi lứa tuổi tại Quy Nhơn.', 'Nơi chứa đựng cả vũ trụ thu nhỏ với các phòng trưng bày khoa học, mô hình vũ trụ trực quan sinh động, là điểm đến giáo dục và giải trí hấp dẫn.',
            'Quy Nhơn, Bình Định', NULL, NULL, 'https://mia.vn/media/uploads/blog-du-lich/trung-tam-kham-pha-khoa-hoc-quy-nhon-noi-kham-pha-ca-vu-tru-thu-nho-1679623373.jpg', 'https://mia.vn/media/uploads/blog-du-lich/trung-tam-kham-pha-khoa-hoc-quy-nhon-noi-kham-pha-ca-vu-tru-thu-nho-1679623373.jpg', '[{"src": "https://mia.vn/media/uploads/blog-du-lich/trung-tam-kham-pha-khoa-hoc-quy-nhon-noi-kham-pha-ca-vu-tru-thu-nho-1679623373.jpg", "alt": "Trung tâm Khám phá Khoa học Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Science Center", "Museum", "Educational"], "sentiment": "Positive", "suitable_for": ["Families", "Children", "Students"]}'::jsonb, '{"urls": ["https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn"], "titles": ["Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
