        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Ông Núi', ARRAY['Linh Phong Thiền Tự','Linh Phong Tự']::text[], 'Ngôi chùa linh thiêng nổi tiếng với tượng Phật khổng lồ tọa sơn vọng hải.', 'Tọa lạc trên đỉnh Chóp Vung, chùa Ông Núi là điểm đến tâm linh quan trọng, nơi du khách có thể cầu bình an, may mắn và chiêm ngưỡng kiệt tác kiến trúc Phật giáo độc đáo.',
            'Cát Tiến, Phù Cát, Bình Định', NULL, NULL, 'https://mia.vn/media/uploads/blog-du-lich/chua-ong-nui-toa-do-linh-thieng-voi-tuong-phat-tua-son-vong-hai-1679021660.jpg', 'https://mia.vn/media/uploads/blog-du-lich/chua-ong-nui-toa-do-linh-thieng-voi-tuong-phat-tua-son-vong-hai-1679021660.jpg', '[{"src": "https://mia.vn/media/uploads/blog-du-lich/chua-ong-nui-toa-do-linh-thieng-voi-tuong-phat-tua-son-vong-hai-1679021660.jpg", "alt": "Chùa Ông Núi Bình Định"}, {"src": "https://cdn.xanhsm.com/2024/12/34f3bc41-chua-quy-nhon-4.jpg", "alt": "Chùa Ông Núi với tượng Phật ngồi lớn tựa núi, hướng ra biển"}]'::jsonb, NULL, NULL,
            NULL, '{"features": ["Tượng Phật khổng lồ", "Tọa sơn vọng hải"], "highlights": ["Tượng Phật ngồi lớn nhất Đông Nam Á cao 69m"]}'::jsonb, '{"tags": ["Pagoda", "Temple", "Spiritual", "Scenic View", "Chùa cổ", "Tượng Phật khổng lồ", "Tâm linh"], "sentiment": "Positive", "suitable_for": ["Pilgrims", "Nature lovers", "Sightseeing", "Khách hành hương", "Người thích leo núi vãn cảnh"], "best_time_to_visit": "Buổi sáng sớm hoặc chiều muộn"}'::jsonb, '{"urls": ["https://mia.vn/cam-nang-du-lich/top-12-bai-bien-quy-nhon-voi-canh-sac-huu-tinh-lan-nuoc-trong-xanh-11808", "https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["bãi biển đẹp hoang sơ ở Quy Nhơn", "chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Top 12 bãi biển Quy Nhơn với cảnh sắc hữu tình, làn nước trong xanh", "Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
