        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi Dứa', ARRAY['Bãi San Hô']::text[], 'Điểm lặn ngắm san hô tự nhiên tuyệt đẹp với hàng trăm loài cá đầy màu sắc gần bãi biển Kỳ Co.', 'Bãi Dứa là khu vực biển nông nổi tiếng với những rặng san hô tự nhiên nhiều màu sắc và các đàn cá bơi lội tung tăng. Du khách thường được đưa đến đây bằng cano sau khi vui chơi tại Kỳ Co để tham gia hoạt động lặn nông (snorkeling) với áo phao và kính lặn.',
            'Nhơn Lý, Quy Nhơn, Bình Định', NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, NULL,
            8.5, '{"activities": ["Lặn ngắm san hô", "Phao thiên nga", "Phao thú nhún", "Thuyền thúng đáy kính"], "ticket_price": "Chi phí lặn ngắm san hô khoảng 50.000 - 100.000 VNĐ (đã bao gồm kính lặn, áo phao)"}'::jsonb, '{"tags": ["Lặn ngắm san hô", "Trải nghiệm biển", "Sinh vật biển", "Bãi biển", "Trải nghiệm thiên nhiên"], "sentiment": "Tích cực, hoạt động thú vị không thể bỏ qua khi đi tour Kỳ Co", "best_time_to_visit": "Ngày nắng ráo, biển êm", "suitable_for": ["Người thích bơi lội", "Gia đình", "Nhóm bạn", "Người thích lặn biển"]}'::jsonb, '{"urls": ["https://cuongdulich.com/dia-diem/2803-kinh-nghiem-du-lich-ky-co-eo-gio.html", "https://dulichquynhon.blog/dia-diem-du-lich/ky-co-eo-gio/"], "queries": ["Kỳ Co Eo Gió Quy Nhơn có gì chơi"], "titles": ["Kinh nghiệm du lịch Kỳ Co - Eo Gió trong 1 ngày chi tiết nhất có kèm ...", "Du Lịch Kỳ Co - Eo Gió: Đường Đi, Giá Vé và Review Chi Tiết"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
