        ) VALUES (
            '9e4a34d7-ab6f-407d-a6ab-87b164922ea8', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'FLC Quy Nhơn Beach & Golf Resort', ARRAY['Resort FLC Quy Nhơn','FLC Quy Nhơn']::text[], 'Quần thể nghỉ dưỡng, resort và sân golf sang trọng nổi tiếng tại khu vực Nhơn Lý.', 'FLC Quy Nhơn là một trong những resort nghỉ dưỡng cao cấp quy mô lớn hàng đầu tại Quy Nhơn, có thể nhìn thấy rõ từ khơi xa khi du khách di chuyển bằng cano ra bãi Kỳ Co.',
            'Nhơn Lý, Quy Nhơn, Bình Định', NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, NULL,
            8.8, '{"class": "Resort 5 sao", "facilities": ["Khách sạn", "Biệt thự", "Sân golf", "Hồ bơi"]}'::jsonb, '{"tags": ["Resort sang trọng", "Nghỉ dưỡng", "Sát biển"], "sentiment": "Tích cực, biểu tượng nghỉ dưỡng cao cấp tại Quy Nhơn", "best_time_to_visit": "Quanh năm", "suitable_for": ["Gia đình", "Cặp đôi", "Khách nghỉ dưỡng cao cấp"]}'::jsonb, '{"urls": ["https://cuongdulich.com/dia-diem/2803-kinh-nghiem-du-lich-ky-co-eo-gio.html"], "queries": ["Kỳ Co Eo Gió Quy Nhơn có gì chơi"], "titles": ["Kinh nghiệm du lịch Kỳ Co - Eo Gió trong 1 ngày chi tiết nhất có kèm ..."]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
