        ) VALUES (
            '7b68aea9-66fa-4083-98d2-0dc2fd5fcc02', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Cầu Tình Yêu Kỳ Co', ARRAY['Cầu Yến']::text[], 'Cây cầu gỗ lãng mạn nằm trong khu du lịch Kỳ Co, điểm check-in chụp ảnh lý tưởng miễn phí.', 'Cầu Tình Yêu (hay còn gọi là Cầu Yến) là một công trình nhân tạo tuyệt đẹp được xây dựng vươn ra biển tại bãi Kỳ Co. Đây là địa điểm check-in sống ảo cực kỳ được yêu thích của các bạn trẻ khi đến với Kỳ Co.',
            'Khu du lịch Kỳ Co, Nhơn Lý, Quy Nhơn, Bình Định', NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, NULL,
            8.3, '{"fee": "Miễn phí chụp hình khi đã vào khu du lịch Kỳ Co"}'::jsonb, '{"tags": ["Điểm check-in", "Chụp ảnh sống ảo", "Cầu gỗ sát biển"], "sentiment": "Rất được yêu thích bởi giới trẻ", "best_time_to_visit": "Ngày nắng đẹp", "suitable_for": ["Cặp đôi", "Bạn trẻ thích chụp ảnh"]}'::jsonb, '{"urls": ["https://cuongdulich.com/dia-diem/2803-kinh-nghiem-du-lich-ky-co-eo-gio.html"], "queries": ["Kỳ Co Eo Gió Quy Nhơn có gì chơi"], "titles": ["Kinh nghiệm du lịch Kỳ Co - Eo Gió trong 1 ngày chi tiết nhất có kèm ..."]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
