        ) VALUES (
            '9d5b0abd-86d7-4c47-8c69-93fb460d3821', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Đầm Thị Nại', ARRAY['Đầm Thị Nại Quy Nhơn']::text[], 'Đầm nước mặn lớn nhất Bình Định, nằm trên tuyến đường di chuyển từ Quy Nhơn đến bán đảo Phương Mai.', 'Đầm Thị Nại là một điểm tham quan tự nhiên rộng lớn, nổi tiếng với cây cầu Thị Nại vượt biển dài nối liền thành phố Quy Nhơn với bán đảo Phương Mai, mang lại cảnh quan sông nước hữu tình.',
