            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'bf60ffd8-32ee-47e8-8e4c-1e547285165f', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Làng chài Nhơn Lý', ARRAY['Xã Nhơn Lý']::text[], 'Làng chài ven biển bình dị với nhịp sống mộc mạc của ngư dân địa phương.', 'Làng chài Nhơn Lý là điểm xuất phát của các chuyến cano ra đảo Kỳ Co. Nơi đây lưu giữ nét đẹp bình dị với những chiếc thuyền thúng, thuyền gỗ đậu san sát ven bờ và là nơi lý tưởng để thưởng thức hải sản tươi ngon với giá cả hợp lý.',
            'Xã Nhơn Lý, Quy Nhơn, Bình Định, Việt Nam', NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, NULL,
            NULL, '{"highlights": ["Thuyền thúng ven bờ", "Hải sản tươi sống", "Nhịp sống làng chài"]}'::jsonb, '{"tags": ["Làng chài", "Văn hóa địa phương", "Hải sản"], "suitable_for": ["Khách du lịch tự túc", "Người muốn trải nghiệm văn hóa bản địa"]}'::jsonb, '{"urls": ["https://dulichquynhon.blog/dia-diem-du-lich/ky-co-eo-gio/"], "queries": ["Kỳ Co Eo Gió Quy Nhơn có gì chơi"], "titles": ["Du Lịch Kỳ Co - Eo Gió: Đường Đi, Giá Vé và Review Chi Tiết"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            '347994c5-389d-438c-a300-6e3b0c80e304', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Quán ăn Anh Nhật Gia Viên', ARRAY['Anh Nhật Gia Viên']::text[], 'Quán ăn nổi tiếng nằm đối diện Tháp Đôi Quy Nhơn, phục vụ các món ăn ngon đặc sản.', 'Nằm đối diện khu di tích Tháp Đôi Quy Nhơn, quán ăn Anh Nhật Gia Viên là địa điểm dừng chân lý tưởng cho du khách sau khi tham quan tháp để thưởng thức các món ăn ngon đặc trưng của địa phương.',
            'Đối diện Tháp Đôi Quy Nhơn, Trần Hưng Đạo, Đống Đa, Thành phố Quy Nhơn, Bình Định', NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Quán ăn ngon", "Đặc sản Bình Định", "Gần Tháp Đôi"], "suitable_for": ["Gia đình", "Nhóm bạn", "Khách du lịch"]}'::jsonb, '{"urls": ["https://cattour.vn/blog/nhung-ngon-thap-cham-quy-nhon-binh-dinh-2071.html"], "queries": ["tháp chàm nổi tiếng ở Quy Nhơn Bình Định"], "titles": ["Những ngọn tháp Chăm Quy Nhơn Bình Định - điểm đến sống ảo, khám phá văn hóa đặc sắc"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'b192353b-66e4-473b-877b-ad7e3a4e891d', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Tháp Chăm Bánh Ít Bình Định', ARRAY['Tháp Bánh Ít','Tháp Bạc']::text[], 'Cụm tháp Chăm cổ kính và nguyên vẹn nhất Bình Định, tọa lạc trên một ngọn đồi lộng gió.', 'Tháp Bánh Ít gồm 4 ngọn tháp nằm trên một ngọn đồi cao khoảng 100m so với mực nước biển, cách trung tâm Quy Nhơn khoảng 18km. Tháp có tên gọi độc đáo này vì hình dáng trông giống như chiếc bánh ít đặc sản Bình Định. Đây là một trong những cụm tháp Chăm lâu đời, giữ được nét hoang sơ, cổ kính và là địa điểm chụp ảnh sống ảo cực kỳ nổi tiếng của giới trẻ.',
            'Thôn Đại Lễ, xã Phước Hiệp, huyện Tuy Phước, tỉnh Bình Định', NULL, NULL, 'https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon.jpg', 'https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon7.jpg', '[{"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon7.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon8.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon9.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon10.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon11.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon12.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon13.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"ticket_price": "20.000đ/người"}'::jsonb, '{"tags": ["Di tích lịch sử", "Sống ảo", "Kiến trúc cổ", "Phong cảnh đẹp"], "suitable_for": ["Giới trẻ", "Người thích chụp ảnh", "Khách du lịch khám phá"], "notes": "Nên đi vào sáng sớm hoặc chiều mát vì buổi trưa trên đồi khá nắng nóng. Bên trong lòng tháp rất mát mẻ tự nhiên."}'::jsonb, '{"urls": ["https://cattour.vn/blog/nhung-ngon-thap-cham-quy-nhon-binh-dinh-2071.html"], "queries": ["tháp chàm nổi tiếng ở Quy Nhơn Bình Định"], "titles": ["Những ngọn tháp Chăm Quy Nhơn Bình Định - điểm đến sống ảo, khám phá văn hóa đặc sắc"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'b192353b-66e4-473b-877b-ad7e3a4e891d', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Tháp Dương Long Bình Định', ARRAY['Tháp Dương Long']::text[], 'Cụm tháp Chăm bằng gạch cao nhất Đông Nam Á, nổi bật với kiến trúc đồ sộ và điêu khắc tinh xảo.', 'Tháp Dương Long là cụm di tích gồm ba tháp Chăm đơn lập (Tháp Bắc, Tháp Trung Tâm và Tháp Nam) tọa lạc trên một gò cao tại huyện Tây Sơn, cách Quy Nhơn khoảng 36km. Tháp Trung Tâm cao tới 39m, là ngọn tháp cao nhất trong cụm. Tháp mang đậm phong cách kiến trúc Bình Định giao thoa với nghệ thuật Khmer, nổi bật với các họa tiết điêu khắc trực tiếp trên đá vô cùng công phu.',
            'Xã Bình Hoà, huyện Tây Sơn, tỉnh Bình Định', NULL, NULL, 'https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon14.jpg', 'https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon15.jpg', '[{"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon14.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}, {"src": "https://cattour.vn/images/upload/images/quy-nhon/thap-cham-quy-nhon/thapchamquynhon15.jpg", "alt": "Tháp Chăm ở Quy Nhơn"}]'::jsonb, NULL, NULL,
            NULL, '{"height": "Tháp Trung Tâm: 39m, Tháp Bắc & Nam: 32m"}'::jsonb, '{"tags": ["Di tích lịch sử", "Kiến trúc Chăm Pa", "Điêu khắc đá", "Tháp Chăm cao nhất"], "suitable_for": ["Người yêu khảo cổ", "Khách du lịch khám phá văn hóa"], "notes": "Do nằm khá xa trung tâm và chưa được khai thác du lịch đại trà, du khách có thể cần liên hệ người giữ khóa tại đây để vào tham quan bên trong."}'::jsonb, '{"urls": ["https://cattour.vn/blog/nhung-ngon-thap-cham-quy-nhon-binh-dinh-2071.html"], "queries": ["tháp chàm nổi tiếng ở Quy Nhơn Bình Định"], "titles": ["Những ngọn tháp Chăm Quy Nhơn Bình Định - điểm đến sống ảo, khám phá văn hóa đặc sắc"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'b192353b-66e4-473b-877b-ad7e3a4e891d', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Twin Towers', ARRAY['Hung Thanh Towers','Tháp Đôi','Tháp Đôi Quy Nhơn']::text[], 'A nearly thousand-year-old Cham tower complex located in the heart of Quy Nhon, consisting of two parallel towers with unique Champa and Khmer architectural influences.', 'The Twin Towers (also known as Hung Thanh Towers) date back to the late 12th and early 13th centuries. The northern tower stands at approximately 22 meters high, while the southern tower is over 17 meters high. It is a unique religious architectural work of the ancient Champa Kingdom, featuring distinctive Binh Dinh architectural style with Khmer cultural influences. Inside, a reproduction of sandstone Linga-Yoni idols is enshrined, symbolizing fertility and abundance.',
            'Tran Hung Dao Street, Dong Da Ward, Quy Nhon City, Binh Dinh Province', NULL, NULL, 'https://vstatic.vietnam.vn/vietnam/resource/IMAGE/2025/1/19/3de1dcd2d30d44298bcd5161c86273c3', 'https://vstatic.vietnam.vn/vietnam/resource/IMAGE/2025/1/19/3de1dcd2d30d44298bcd5161c86273c3', '[{"src": "https://vstatic.vietnam.vn/vietnam/resource/IMAGE/2025/1/19/3de1dcd2d30d44298bcd5161c86273c3", "alt": "Discover the nearly thousand-year-old Cham Tower in the seaside city of Quy Nhon - Photo 1."}, {"src": "https://vstatic.vietnam.vn/vietnam/resource/IMAGE/2025/1/19/2f80c7e6a2164491b03bcd0e9ba9808b", "alt": "Discover the nearly thousand-year-old Cham Tower in the seaside town of Quy Nhon - Photo 2."}, {"src": "https://vstatic.vietnam.vn/vietnam/resource/IMAGE/2025/1/19/dcbffdacaaa74c37ad4cc54495cbd5c5", "alt": "Discover the nearly thousand-year-old Cham Tower amidst the coastal city of Quy Nhon - Photo 3."}, {"src": "https://vstatic.vietnam.vn/vietnam/resource/IMAGE/2025/1/19/a38884470c144afdad4df3fecd9c7aeb", "alt": "Discover the nearly thousand-year-old Cham Tower amidst the coastal city of Quy Nhon - Photo 4."}, {"src": "https://vstatic.vietnam.vn/vietnam/resource/IMAGE/2025/1/19/b4e0d9cd099b466f807dc0128fa70b64", "alt": "Discover the nearly thousand-year-old Cham Tower amidst the coastal city of Quy Nhon - Photo 5."}, {"src": "https://vstatic.vietnam.vn/vietnam/resource/IMAGE/2025/1/19/ccd022c4f7f641a9b679c275f28b3938", "alt": "Discover the nearly thousand-year-old Cham Tower amidst the coastal city of Quy Nhon - Photo 6."}, {"src": "https://vstatic.vietnam.vn/vietnam/resource/IMAGE/2025/1/19/b2d16fdab119414b92369d913241e0b2", "alt": "Discover the nearly thousand-year-old Cham Tower amidst the coastal city of Quy Nhon - Photo 7."}, {"src": "https://vstatic.vietnam.vn/vietnam/resource/IMAGE/2025/1/19/f0972ceb619e4418a483cda90fdc65c6", "alt": "Discover the nearly thousand-year-old Cham Tower amidst the coastal city of Quy Nhon - Photo 8."}]'::jsonb, NULL, NULL,
            NULL, '{"height": {"northern_tower": "approximately 22 meters", "southern_tower": "over 17 meters"}, "architectural_style": "Binh Dinh style with Khmer influences", "historical_period": "Late 12th to early 13th century", "enshrined_relics": "Linga-Yoni idols made of sandstone"}'::jsonb, '{"tags": ["Cham Towers", "Historical Site", "Ancient Architecture", "Quy Nhon Attractions"], "suitable_for": ["History buffs", "Culture lovers", "Photographers", "Families"], "best_time_to_visit": "Dry season (January to August), preferably early morning or late afternoon to avoid the midday heat.", "sentiment": "Highly positive, noted as an attractive and unique destination for domestic and international tourists."}'::jsonb, '{"urls": ["https://www.vietnam.vn/en/kham-pha-thap-cham-gan-nghin-tuoi-giua-pho-bien-quy-nhon"], "queries": ["tháp chàm nổi tiếng ở Quy Nhơn Bình Định"], "titles": ["Discover the nearly thousand-year-old Cham Tower in the middle of Quy Nhon beach town"], "page_title": "Discover the nearly thousand-year-old Cham Towers amidst the coastal city of Quy Nhon."}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Thiên Hưng', ARRAY['Chùa Thiên Hưng Bình Định','Phượng Hoàng Cổ Trấn của Việt Nam']::text[], 'Ngôi chùa nổi tiếng với phong cách kiến trúc hài hòa, tọa lạc giữa không gian cổ kính và yên bình tại Bình Định.', 'Dù được xây dựng ở thời điểm hiện đại, chùa Thiên Hưng vẫn mang đậm nét cổ kính, thanh tịnh và hài hòa với thiên nhiên xung quanh. Nơi đây được xem là một trong những điểm sinh hoạt tín ngưỡng linh thiêng và thu hút đông đảo du khách đến chiêm bái, tìm kiếm sự tĩnh tâm.',
            'Phường Nhơn Hưng, thị xã An Nhơn, tỉnh Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/1d47f482-chua-quy-nhon-2.jpg', 'https://cdn.xanhsm.com/2024/12/1d47f482-chua-quy-nhon-2.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/1d47f482-chua-quy-nhon-2.jpg", "alt": "Chùa Thiên Hưng với kiến trúc độc đáo, pha lẫn giữa nét cổ kính và hiện đại"}]'::jsonb, NULL, NULL,
            NULL, '{"scenery": "Cổ kính, yên bình, phong cảnh đẹp", "highlights": ["Lưu giữ Ngọc Xá Lợi của Phật tổ Thích Ca Mâu Ni"]}'::jsonb, '{"tags": ["Kiến trúc đẹp", "Tâm linh", "Thanh tịnh", "Check-in", "Chùa", "Kiến trúc cổ kính"], "sentiment": "Tích cực", "suitable_for": ["Khách du lịch", "Người yêu thiên nhiên", "Khách hành hương", "Phật tử", "Khách du lịch tâm linh", "Người yêu thích kiến trúc cổ"], "best_time_to_visit": "Buổi sáng sớm hoặc chiều muộn"}'::jsonb, '{"urls": ["https://dulichvietdu.com.vn/cac-ngoi-chua-o-quy-nhon-noi-tieng/", "https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Gợi ý 15+ ngôi chùa ở Quy Nhơn nổi tiếng", "Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Linh Phong', ARRAY['Chùa Ông Núi']::text[], 'Ngôi chùa nổi tiếng với tượng Phật Thích Ca Mâu Ni ngự tòa sen được xem là cao nhất Đông Nam Á.', 'Chùa Linh Phong (hay chùa Ông Núi) nổi bật với đại tượng Phật Thích Ca Mâu Ni cao 69m ngự trên tòa sen ở lưng chừng núi Bà, hướng nhìn ra biển Đông. Phía dưới tượng Phật là Trung tâm thuyết pháp Phật giáo, hành lang La Hán, thư viện và bảo tàng Xá Lợi Phật, tạo nên một quần thể du lịch tâm linh vô cùng hoành tráng.',
            'Xã Cát Tiến, huyện Phù Cát, tỉnh Bình Định', NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, NULL,
            NULL, '{"statue_height": "69m", "elevation": "129m so với mặt nước biển", "key_features": "Tượng Phật Thích Ca cao nhất Đông Nam Á, Bảo tàng Xá Lợi Phật"}'::jsonb, '{"tags": ["Tượng Phật khổng lồ", "Tâm linh", "Ngắm cảnh biển", "Núi Bà"], "sentiment": "Tích cực", "suitable_for": ["Khách hành hương", "Người thích leo núi", "Khách du lịch tâm linh"]}'::jsonb, '{"urls": ["https://dulichvietdu.com.vn/cac-ngoi-chua-o-quy-nhon-noi-tieng/"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Gợi ý 15+ ngôi chùa ở Quy Nhơn nổi tiếng"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Minh Tịnh', ARRAY[]::text[], 'Ngôi chùa cổ kính hơn 100 năm tuổi, chứng nhân lịch sử cho sự đổi thay của thành phố biển Quy Nhơn.', 'Chùa Minh Tịnh được sáng lập vào năm 1917 bởi Hòa thượng Thích Huệ Pháp. Trải qua hơn một thế kỷ tọa lạc tại Quy Nhơn, ngôi chùa đã được triều đình Huế ban Sắc tứ biển ngạch vào năm 1944 và hiện là nơi sinh hoạt văn hóa tâm linh không thể thiếu của người dân địa phương.',
            'Số 35 Hàm Nghi, phường Ngô Mây, thành phố Quy Nhơn, tỉnh Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/88184cd1-chua-quy-nhon-8.jpg', 'https://cdn.xanhsm.com/2024/12/88184cd1-chua-quy-nhon-8.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/88184cd1-chua-quy-nhon-8.jpg", "alt": "Chùa Minh Tịnh với ngọn tháp cao nổi bật giữa không gian"}]'::jsonb, NULL, NULL,
            NULL, '{"founded_year": "1917", "founder": "Hòa thượng Thích Huệ Pháp", "historical_relic": "Sắc tứ biển ngạch từ triều đình Huế (1944)"}'::jsonb, '{"tags": ["Chùa cổ", "Hơn 100 năm tuổi", "Tâm linh", "Nội thành Quy Nhơn", "Tháp cao", "Kiến trúc đẹp", "Điểm tâm linh mới"], "sentiment": "Tích cực", "suitable_for": ["Người dân địa phương", "Khách hành hương", "Người thích không gian cổ kính", "Khách du lịch", "Người đi lễ"]}'::jsonb, '{"urls": ["https://dulichvietdu.com.vn/cac-ngoi-chua-o-quy-nhon-noi-tieng/", "https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Gợi ý 15+ ngôi chùa ở Quy Nhơn nổi tiếng", "Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Bích Nam', ARRAY[]::text[], 'Ngôi chùa mới khánh thành cuối năm 2019 với quy mô hoành tráng, tráng lệ và thanh tịnh tại Tuy Phước.', 'Chùa Bích Nam tọa lạc tại huyện Tuy Phước, được thành lập vào cuối năm 2019. Ngôi chùa gây ấn tượng mạnh mẽ với du khách bởi không gian vô cùng uy nghiêm, tráng lệ nhưng vẫn giữ được nét thanh tịnh, yên bình đặc trưng của chốn thiền môn.',
            'Thôn Quảng Nghiệp, xã Phước Hưng, huyện Tuy Phước, tỉnh Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/ac34b9eb-chua-quy-nhon-11.jpg', 'https://cdn.xanhsm.com/2024/12/ac34b9eb-chua-quy-nhon-11.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/ac34b9eb-chua-quy-nhon-11.jpg", "alt": "Chùa Bích Nam với kiến trúc truyền thống, nằm bên cạnh dòng sông Hà Thanh"}]'::jsonb, NULL, NULL,
            NULL, '{"founded_year": "2019", "scenery": "Hoành tráng, uy nghiêm, tráng lệ"}'::jsonb, '{"tags": ["Chùa mới", "Kiến trúc hoành tráng", "Thanh tịnh", "Tuy Phước", "Chùa ven sông", "Thời nhà Nguyễn", "Thanh bình"], "sentiment": "Tích cực", "suitable_for": ["Khách du lịch", "Khách hành hương", "Người thích chụp ảnh kiến trúc", "Người tìm kiếm sự yên bình"]}'::jsonb, '{"urls": ["https://dulichvietdu.com.vn/cac-ngoi-chua-o-quy-nhon-noi-tieng/", "https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Gợi ý 15+ ngôi chùa ở Quy Nhơn nổi tiếng", "Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Tâm Ấn', ARRAY['Tâm Ấn Ni Tự']::text[], 'Ngôi chùa Ni nổi tiếng nằm ngay trung tâm thành phố Quy Nhơn với diện tích rộng rãi và thanh tịnh.', 'Chùa Tâm Ấn (Tâm Ấn Ni Tự) được khởi công xây dựng vào năm 1956 bởi Sư cô Tâm Hoa trên mảnh đất hiến tặng của một tín nữ mộ đạo. Ngôi chùa có diện tích khoảng 2.000 mét vuông với cổng Tam quan hướng Đông, là nơi tu học của các Ni sư và là điểm tựa tâm linh của người dân thành phố biển.',
            'Số 58B Ngô Quyền, phường Lê Lợi, thành phố Quy Nhơn, tỉnh Bình Định', NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, NULL,
            NULL, '{"founded_year": "1956", "founder": "Sư cô Tâm Hoa", "area": "Khoảng 2000m2"}'::jsonb, '{"tags": ["Chùa Ni", "Trung tâm Quy Nhơn", "Tâm linh", "Thanh tịnh"], "sentiment": "Tích cực", "suitable_for": ["Khách hành hương", "Người dân địa phương", "Nữ giới chiêm bái"]}'::jsonb, '{"urls": ["https://dulichvietdu.com.vn/cac-ngoi-chua-o-quy-nhon-noi-tieng/"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Gợi ý 15+ ngôi chùa ở Quy Nhơn nổi tiếng"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Ông Nhiêu', ARRAY['Đền Quan Thánh']::text[], 'Công trình kiến trúc dân gian gần 200 năm tuổi, gắn liền với tín ngưỡng và lịch sử phát triển đô thị cổ Quy Nhơn.', 'Được xây dựng từ năm 1837, Chùa Ông Nhiêu (hay Đền Quan Thánh) là một di tích lịch sử văn hóa dân gian đặc sắc tại Quy Nhơn. Trải qua nhiều lần trùng tu, nơi đây vẫn giữ được nét kiến trúc cổ kính, thể hiện ước vọng bình an của người dân và là điểm đến hấp dẫn cho những ai muốn tìm hiểu văn hóa tín ngưỡng xưa.',
            'Số 253 Bạch Đằng, phường Trần Hưng Đạo, thành phố Quy Nhơn, tỉnh Bình Định', NULL, NULL, 'https://dulichvietdu.com.vn/wp-content/uploads/2023/08/Chua-o-Quy-Nhon-noi-tieng-1.png', 'https://dulichvietdu.com.vn/wp-content/uploads/2023/08/Chua-o-Quy-Nhon-noi-tieng-1.png', '[{"src": "https://dulichvietdu.com.vn/wp-content/uploads/2023/08/Chua-o-Quy-Nhon-noi-tieng-1.png", "alt": "Chùa Ông Nhiêu Quy Nhơn"}, {"src": "https://cdn.xanhsm.com/2024/12/ceee77ee-chua-quy-nhon-7.jpg", "alt": "Chùa Ông Nhiêu với kiến trúc đơn giản, mang dấu ấn của người Chăm"}]'::jsonb, NULL, NULL,
            NULL, '{"founded_year": "1837", "architectural_style": "Kiến trúc dân gian cổ kính"}'::jsonb, '{"tags": ["Chùa cổ", "Đền thờ", "Gần 200 năm tuổi", "Văn hóa dân gian", "Giao thoa văn hóa", "Văn hóa Chăm", "Lịch sử"], "sentiment": "Tích cực", "suitable_for": ["Người thích tìm hiểu lịch sử", "Khách hành hương", "Khách du lịch văn hóa", "Người yêu lịch sử"]}'::jsonb, '{"urls": ["https://dulichvietdu.com.vn/cac-ngoi-chua-o-quy-nhon-noi-tieng/", "https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Gợi ý 15+ ngôi chùa ở Quy Nhơn nổi tiếng", "Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Bà Nước Mặn', ARRAY[]::text[], 'Ngôi chùa linh thiêng nằm ngay bên bờ biển Quy Nhơn, gắn bó mật thiết với đời sống ngư dân địa phương.', 'Từ xa xưa, người dân đã đến chùa Bà Nước Mặn để cầu bình an, thuận buồm xuôi gió cho những chuyến ra khơi. Chùa mang nét đẹp kiến trúc dân gian, gần gũi và ấm cúng.',
            'Bên bờ biển Quy Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/709e82b5-chua-quy-nhon-5.jpg', 'https://cdn.xanhsm.com/2024/12/709e82b5-chua-quy-nhon-5.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/709e82b5-chua-quy-nhon-5.jpg", "alt": "Chùa Bà Nước Mặn với không gian gần gũi ấm cúng"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Chùa ven biển", "Tâm linh ngư dân", "Kiến trúc dân gian"], "suitable_for": ["Khách du lịch tâm linh", "Người muốn tìm hiểu văn hóa bản địa"]}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
            address, lat, lng, thumbnail, cover_image, images, rating, review_count,
