        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Thập Tháp', ARRAY['Chùa Thập Tháp Di Đà']::text[], 'Một trong những ngôi chùa cổ nhất của tỉnh Bình Định, được xây dựng từ thời nhà Lý.', 'Chùa Thập Tháp được xây dựng trên nền 10 ngôi tháp Chăm cổ nên mang tên Thập Tháp. Chùa vẫn giữ được nét cổ kính, trang nghiêm và là điểm đến tâm linh quan trọng.',
            'Thị trấn An Nhơn, huyện An Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/63f76b61-chua-quy-nhon-9.jpg', 'https://cdn.xanhsm.com/2024/12/63f76b61-chua-quy-nhon-9.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/63f76b61-chua-quy-nhon-9.jpg", "alt": "Chùa Thập Tháp với kiến trúc cổ kính, nằm giữa không gian yên tĩnh"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Chùa cổ nhất", "Thời nhà Lý", "Tháp Chăm cổ"], "suitable_for": ["Người yêu lịch sử", "Khách hành hương"]}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
            category_id, division_id, name, aliases, short_description, description,
