        ) VALUES (
            'd6207cce-2760-4f3f-ab40-4c2743f46896', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Chùa Sơn Long', ARRAY[]::text[], 'Ngôi chùa độc đáo ẩn mình trong một hang động tự nhiên trên dãy núi Vũng Chua.', 'Chùa Sơn Long được bao quanh bởi cây cối xanh tươi, tạo nên một không gian yên tĩnh, thoát tục. Kiến trúc chùa mang nhiều nét độc đáo, hài hòa với thiên nhiên.',
            'Dãy núi Vũng Chua, cách trung tâm thành phố Quy Nhơn khoảng 10km, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/376d0339-chua-quy-nhon-10.jpg', 'https://cdn.xanhsm.com/2024/12/376d0339-chua-quy-nhon-10.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/376d0339-chua-quy-nhon-10.jpg", "alt": "Chùa Sơn Long nằm ẩn mình trong hang đá, bao quanh là cây cối xanh tươi"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Chùa trong hang đá", "Núi Vũng Chua", "Thiên nhiên hoang sơ"], "suitable_for": ["Người thích khám phá", "Khách du lịch tâm linh"]}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
INSERT INTO places (
