            popularity_score, attributes, ai_data, source_data, status, created_by
        ) VALUES (
            'f5407781-07d1-42a8-8b5a-09f22986aac9', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Ghềnh Ráng', ARRAY['Ghềnh Ráng Tiên Sa']::text[], 'Khu du lịch nổi tiếng với vẻ đẹp hoang sơ của những mỏm đá và bãi tắm Hoàng Hậu.', 'Ghềnh Ráng sở hữu những mỏm đá nhiều hình thù kỳ thú và biển xanh bao la, là một trong những danh lam thắng cảnh không thể bỏ qua khi đến Quy Nhơn.',
            'Quy Nhơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/1f1d7e3d-chua-quy-nhon-12.jpg', 'https://cdn.xanhsm.com/2024/12/1f1d7e3d-chua-quy-nhon-12.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/1f1d7e3d-chua-quy-nhon-12.jpg", "alt": "Ghềnh Ráng với những mỏm đá nhiều hình thù kỳ thú và biển xanh bao la"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Danh lam thắng cảnh", "Bãi đá đẹp", "Bãi tắm Hoàng Hậu"], "suitable_for": ["Khách du lịch", "Người thích chụp ảnh"]}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
