        ) VALUES (
            'c263a016-913f-4319-8411-af552b9255ba', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bãi biển Cát Tiến', ARRAY[]::text[], 'Bãi biển hoang sơ với bờ cát trắng mịn và nước biển xanh trong dưới chân núi.', 'Nằm ngay dưới chân núi gần chùa Ông Núi, bãi biển Cát Tiến là địa điểm lý tưởng để tắm biển và thư giãn sau chuyến hành hương.',
            'Cát Tiến, Phù Cát, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/fcffd7e4-chua-quy-nhon-13.jpg', 'https://cdn.xanhsm.com/2024/12/fcffd7e4-chua-quy-nhon-13.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/fcffd7e4-chua-quy-nhon-13.jpg", "alt": "Bãi biển Cát Tiến với bờ cát trắng mịn, nước biển xanh trong"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Bãi biển", "Cát trắng mịn", "Tắm biển"], "suitable_for": ["Gia đình", "Nhóm bạn", "Người yêu biển"]}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
