        ) VALUES (
            '11686bce-c7ba-4966-9de9-23f9e50ca18d', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Bảo tàng Quang Trung', ARRAY[]::text[], 'Nơi lưu giữ nhiều hiện vật và tài liệu về vị anh hùng áo vải Quang Trung - Nguyễn Huệ.', 'Bảo tàng Quang Trung sở hữu kiến trúc truyền thống và là nơi lưu giữ nhiều hiện vật lịch sử quý giá về phong trào Tây Sơn và người anh hùng Quang Trung.',
            'Huyện Tây Sơn, Bình Định', NULL, NULL, 'https://cdn.xanhsm.com/2024/12/fb8b1cd1-chua-quy-nhon-15.jpg', 'https://cdn.xanhsm.com/2024/12/fb8b1cd1-chua-quy-nhon-15.jpg', '[{"src": "https://cdn.xanhsm.com/2024/12/fb8b1cd1-chua-quy-nhon-15.jpg", "alt": "Bảo tàng Quang Trung với kiến trúc truyền thống và nhiều hiện vật lịch sử quý giá"}]'::jsonb, NULL, NULL,
            NULL, '{}'::jsonb, '{"tags": ["Bảo tàng", "Lịch sử", "Quang Trung Nguyễn Huệ"], "suitable_for": ["Học sinh sinh viên", "Người yêu lịch sử", "Khách du lịch"]}'::jsonb, '{"urls": ["https://www.greensm.com/vn-vi/news/chua-o-quy-nhon"], "queries": ["chùa đẹp thanh tịnh ở Quy Nhơn"], "titles": ["Top 10 ngôi chùa linh thiêng và nổi tiếng ở Quy Nhơn | Green SM"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
