            'Khu du lịch Ghềnh Ráng - Tiên Sa, Quy Nhơn, Bình Định', NULL, NULL, 'https://static2.abay.vn/Images/2023/06/30/khu-mo-han-mac-tu-compressed.jpg', 'https://static2.abay.vn/Images/2023/06/30/khu-mo-han-mac-tu-compressed.jpg', '[{"src": "https://static2.abay.vn/Images/2023/06/30/khu-mo-han-mac-tu-compressed.jpg", "alt": "khu-mo-han-mac-tu"}]'::jsonb, NULL, NULL,
