        ) VALUES (
            'b192353b-66e4-473b-877b-ad7e3a4e891d', 'b51a93cd-9782-46a0-933a-68c19ecb9586', 'Làng phong Quy Hòa', ARRAY['Trại phong Quy Hòa','Bệnh viện Phong - Da liễu Trung ương Quy Hòa']::text[], 'Ngôi làng yên bình, mộc mạc nằm cách khu du lịch Ghềnh Ráng khoảng 3km.', 'Được xây dựng vào năm 1929 bởi linh mục người Pháp Paul Maheu, làng phong Quy Hòa mang vẻ đẹp an yên, mộc mạc và bình dị, tách biệt hoàn toàn với sự ồn ào, khói bụi của phố thị.',
            'Đường Mộng Cầm, Quy Nhơn, Bình Định', NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, NULL,
            NULL, '{"year_built": 1929, "founder": "Linh mục Paul Maheu"}'::jsonb, '{"tags": ["Làng cổ", "Điểm check-in", "Yên bình", "Lịch sử"], "sentiment": "Positive", "best_time_to_visit": "Ban ngày", "suitable_for": ["Người thích khám phá", "Nhiếp ảnh gia", "Khách du lịch tìm kiếm sự yên bình"], "notes": "Không khí vô cùng trong lành, không có khói bụi hay tiếng còi xe ồn ào."}'::jsonb, '{"urls": ["https://www.abay.vn/tin-tuc/top-diem-check-in-sieu-dep-o-quy-nhon-cho-team-me-song-ao.aspx"], "queries": ["địa điểm check-in sống ảo đẹp nhất Quy Nhơn"], "titles": ["Top điểm check-in siêu đẹp ở Quy Nhơn cho team mê “sống ảo”"]}'::jsonb, 'active', '00000000-0000-0000-0000-000000000000'
        );
