            'Quy Hòa, Quy Nhơn, Bình Định', NULL, NULL, 'https://static2.abay.vn/Images/2023/06/30/bien-quy-hoa-compressed.jpg', 'https://static2.abay.vn/Images/2023/06/30/bien-quy-hoa-compressed.jpg', '[{"src": "https://static2.abay.vn/Images/2023/06/30/bien-quy-hoa-compressed.jpg", "alt": "bien-quy-hoa"}]'::jsonb, NULL, NULL,
